custom_css:
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@400;500&family=Noto+Serif+KR:wght@400;500&display=swap');
/* 캐와 펠소 이름 글꼴 지정 */

/* 이름부분 폰트 최상위 부모 선택자까지 지정해서 강제로 우선순위 부여 */
#chat .mes .name_text,
.mes_block .name_text,
div.flex-container span.name_text {
        font-family: 'Cormorant Garamond', Georgia, serif !important;
    font-size: 1.5em !important;
    font-weight: normal !important;
    letter-spacing: 0.3px !important;
    display: inline-flex !important;
    align-items: center !important;
}

/* 내부 버튼 그룹 및 이모지 깨짐 방지 */
#chat .mes .name_text .cat-btn-group,
#chat .mes .name_text .cat-emoji-icon,
#chat .mes .name_text i {
    font-family: var(--main-font, sans-serif) !important;
}

/* 여기서부터 본문 */

body, .mes_text {
  color: rgba(17, 17, 17, 1) !important;
}

.mes {
  background: transparent !important;
  box-shadow: none !important;
  border: none !important;
  border-bottom: 1px solid rgba(229, 229, 229, 1) !important;
  border-radius: 0 !important;
  padding: 16px 4px !important;
}

.mes .avatar, .mesAvatarWrapper {
  display: none !important;
}

.mes .ch_name .name_text {
  font-family: 'Noto Sans KR', sans-serif !important;
  font-size: 13px !important;
  font-weight: 500 !important;
  color: #000 !important;
}

/* 대사 하이라이트 스타일 변경 */
.mes_text q, .mes_text .quote {
  text-decoration: underline !important;
  color: rgba(17, 17, 17, 1) !important;
  font-style: normal !important;
}

.mes_text em, .mes_text i {
  font-style: italic !important;
  color: rgba(119, 119, 119, 1) !important;
}

#send_form, #form_sheld {
  background: #fff !important;
  box-shadow: none !important;
  border-top: 1px solid rgba(229, 229, 229, 1) !important;
}

#send_textarea {
  font-family: inherit;
  border: 1px solid #ddd !important;
  border-radius: 8px !important;
  background: #fff !important;
  box-shadow: none !important;
}

.mes_buttons button, .mes_buttons i {
  box-shadow: none !important;
  text-shadow: none !important;
  filter: none !important;
}

::-webkit-scrollbar {
  width: 8px;
}
::-webkit-scrollbar-thumb {
  background: #ddd;
  border-radius: 4px;
}


/* 여기부터 */

/* 1. 상단 익스텐션 바 그림자 제거 */
#extensionTopBar,
#top-bar,
#top-settings-holder {
  box-shadow: none !important;
  border: none !important;
  background: #fff !important;
}

#extensionTopBar i,
#extensionTopBar select,
#extensionTopBar input {
  box-shadow: none !important;
  text-shadow: none !important;
  filter: none !important;
}

/* 2. select 박스들 (프리셋 선택 등) 테마에 맞춰 통일 */
select,
.text_pole,
select.text_pole {
  background: #fff !important;
  color: rgba(17, 17, 17, 1) !important;
  border: 1px solid #ddd !important;
  box-shadow: none !important;
  border-radius: 8px !important;
  font-family: 'Noto Serif KR', Georgia, serif !important;
}

select option {
  background: #fff !important;
  color: rgba(17, 17, 17, 1) !important;
}

/* 3. inline-drawer 헤더 (이미지 생성 등 확장 드로어) */
.inline-drawer-toggle,
.inline-drawer-header {
  background: #fff !important;
  box-shadow: none !important;
  border: none !important;
  border-bottom: 1px solid rgba(229, 229, 229, 1) !important;
  color: rgba(17, 17, 17, 1) !important;
}

.inline-drawer-toggle b,
.inline-drawer-header b,
.inline-drawer-toggle span,
.inline-drawer-header span {
  color: rgba(17, 17, 17, 1) !important;
  text-shadow: none !important;
}

.inline-drawer-icon {
  color: rgba(119, 119, 119, 1) !important;
  text-shadow: none !important;
  filter: none !important;
}

/* 4. 섹션 헤더 (OpenAI 사전 설정, 컨텍스트 템플릿, UI 테마, Current Persona 등) */
.standoutHeader,
.title_restorable,
h4.title_restorable {
  background: #fff !important;
  box-shadow: none !important;
  border: none !important;
  border-bottom: 1px solid rgba(229, 229, 229, 1) !important;
  color: rgba(17, 17, 17, 1) !important;
  text-shadow: none !important;
}

.standoutHeader strong,
.standoutHeader span,
.title_restorable span,
.title_restorable div {
  color: rgba(17, 17, 17, 1) !important;
  text-shadow: none !important;
}

/* 5. menu_button (가져오기/내보내기/삭제 등 아이콘 버튼) */
.menu_button,
.menu_button_icon {
  background: #fff !important;
  border: 1px solid #ddd !important;
  box-shadow: none !important;
  text-shadow: none !important;
  color: rgba(17, 17, 17, 1) !important;
  border-radius: 8px !important;
}

.menu_button:hover,
.menu_button_icon:hover {
  background: #f5f5f5 !important;
}

.menu_button i,
.menu_button_icon i {
  color: rgba(17, 17, 17, 1) !important;
  filter: none !important;
  text-shadow: none !important;
}

/* 6. select2 드롭다운 (월드 인포 선택 등) */
.select2-container .select2-selection--single,
.select2-selection {
  background: #fff !important;
  border: 1px solid #ddd !important;
  box-shadow: none !important;
  border-radius: 8px !important;
  font-family: 'Noto Serif KR', Georgia, serif !important;
}

.select2-selection__rendered {
  color: rgba(17, 17, 17, 1) !important;
}

.select2-selection__arrow b {
  border-color: rgba(119, 119, 119, 1) transparent transparent transparent !important;
}

.select2-search__field,
.select2-dropdown {
  background: #fff !important;
  color: rgba(17, 17, 17, 1) !important;
  border: 1px solid #ddd !important;
  box-shadow: none !important;
}

.select2-results__option {
  color: rgba(17, 17, 17, 1) !important;
}

.select2-results__option--highlighted {
  background: #f0f0f0 !important;
  color: rgba(17, 17, 17, 1) !important;
}

/* 7. 기타 섹션 헤더 (캐릭터 처리, 채팅/메시지 처리, 기타 등 - h4 전체) */
h4 {
  background: #fff !important;
  box-shadow: none !important;
  border: none !important;
  border-bottom: 1px solid rgba(229, 229, 229, 1) !important;
  color: rgba(17, 17, 17, 1) !important;
  text-shadow: none !important;
  font-family: 'Noto Sans KR', sans-serif !important;
}

h4 span {
  color: rgba(17, 17, 17, 1) !important;
  text-shadow: none !important;
}

/* 8. 프롬프트 매니저 목록 텍스트 - 흰 배경에 흰 글씨 방지 */
.completion_prompt_manager_prompt,
.completion_prompt_manager_prompt_name,
.completion_prompt_manager_prompt a,
.prompt-manager-inspect-action,
.prompt_manager_prompt_tokens {
  color: rgba(17, 17, 17, 1) !important;
  text-shadow: none !important;
  filter: none !important;
  opacity: 1 !important;
}

.completion_prompt_manager_prompt_name .fa-asterisk,
.completion_prompt_manager_prompt_name .fa-user {
  color: rgba(119, 119, 119, 1) !important;
}

.prompt_manager_prompt_controls span {
  color: rgba(119, 119, 119, 1) !important;
  text-shadow: none !important;
}

.prompt_manager_prompt_controls span.caution {
  color: #c0392b !important;
}

/* 비활성화된 프롬프트도 완전히 안 보이지 않게 */
.completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name,
.completion_prompt_manager_prompt_disabled a {
  color: rgba(119, 119, 119, 1) !important;
  opacity: 0.7 !important;
}

/* "프롬프트" 타이틀 - blur/투명도 효과 제거 + 진하게 */
#PromptManagerModule .inline-drawer-header,
[data-i18n="Prompts"] {
  filter: none !important;
  -webkit-filter: none !important;
  backdrop-filter: none !important;
  opacity: 1 !important;
  text-shadow: none !important;
  color: rgba(17, 17, 17, 1) !important;
  font-weight: 600 !important;
}

.inline-drawer-header b,
.inline-drawer-header b span {
  filter: none !important;
  opacity: 1 !important;
  text-shadow: none !important;
  color: rgba(17, 17, 17, 1) !important;
}

/* 채팅 영역 전체를 화면 중앙에 배치 */
#sheld, #chat {
  margin-left: auto !important;
  margin-right: auto !important;
}

/* 메시지 입력창 테두리 제거 (박스 느낌 없애기) */
#send_textarea {
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
  background: transparent !important;
}

#send_textarea:focus {
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
}

/* ===== 상단 네비게이션 아이콘 10개 커스텀 이미지로 교체 ===== */
/* 각 항목의 url("...") 안에 base64 data URL만 붙여넣으면 바로 적용됩니다 */

#leftNavDrawerIcon,
#API-status-top,
.drawer-icon.fa-font,
#WIDrawerIcon,
.drawer-icon.fa-user-cog,
.drawer-icon.fa-panorama,
.drawer-icon.fa-cubes,
.drawer-icon.fa-face-smile,
#rightNavDrawerIcon {
  font-size: 0 !important; /* 기존 폰트어썸 글자 숨김 */
  width: 22px !important;
  height: 22px !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
}

#leftNavDrawerIcon::before,
#API-status-top::before,
.drawer-icon.fa-font::before,
#WIDrawerIcon::before,
.drawer-icon.fa-user-cog::before,
.drawer-icon.fa-panorama::before,
.drawer-icon.fa-cubes::before,
.drawer-icon.fa-face-smile::before,
#rightNavDrawerIcon::before {
  content: "" !important;
  display: block !important;
  width: 20px !important;
  height: 20px !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
}

/* 1. 전송 대기 상태일 때만 커스텀 전송 SVG 출력 */
#send_but.fa-paper-plane::before {
  content: "" !important;
  display: block !important;
  width: 20px !important;
  height: 20px !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-image: url("data:image/svg+xml;base64,") !important;
}

/* 2. 생성 중(Stop 상태)일 때는 커스텀 SVG를 끄고 정지 아이콘 정상 표시 */
#send_but.fa-circle-stop::before {
  content: "\f28d" !important; /* 폰트어썸 정지(circle-stop) 유니코드 */
  font-family: "Font Awesome 6 Free", "FontAwesome" !important;
  font-weight: 900 !important;
  font-size: 18px !important;
  background-image: none !important;
  color: #111111 !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
}

/* 3. 위치 미세 조정 (전송/중단 공통 동기화) */
#send_but {
  position: relative !important;
  right: 9px !important;
  bottom: 6px !important;
  cursor: pointer !important;
}

/* 2. AI 응답 구성 */
#leftNavDrawerIcon::before {
  background-image: url("data:image/svg+xml;base64,") !important;
}

/* 3. API 연결 */
#API-status-top::before {
  background-image: url("data:image/svg+xml;base64,") !important;
}

/* 4. AI 응답 형식 지정 */
.drawer-icon.fa-font::before {
  background-image: url("data:image/svg+xml;base64,") !important;
}

/* 5. 월드 인포 */
#WIDrawerIcon::before {
  background-image: url("data:image/svg+xml;base64,") !important;
}

/* 6. 사용자 설정 */
.drawer-icon.fa-user-cog::before {
  background-image: url("data:image/svg+xml;base64,") !important;
}

/* 7. (배경/파노라마 아이콘) */
.drawer-icon.fa-panorama::before {
  background-image: url("data:image/svg+xml;base64,") !important;
}

/* 8. 확장 */
.drawer-icon.fa-cubes::before {
  background-image: url("data:image/svg+xml;base64,") !important;
}

/* 9. 페르소나 관리 */
.drawer-icon.fa-face-smile::before {
  background-image: url("data:image/svg+xml;base64,") !important;
}

/* 10. 캐릭터 관리 */
#rightNavDrawerIcon::before {
  background-image: url("data:image/svg+xml;base64,") !important;
}


/* 모바일 화면에서 채팅/캐릭터 목록이 넘치는 문제 방지 */
@media (max-width: 768px) {
  #sheld, #chat, #right-nav-panel, #character_popup,
  #rm_print_characters_block, .rm_group_view {
    width: 100% !important;
    max-width: 100vw !important;
    margin-left: 0 !important;
    margin-right: 0 !important;
    box-sizing: border-box !important;
    overflow-x: hidden !important;
  }

  body {
    overflow-x: hidden !important;
  }
}

/* 2. 텍스트 영역이 남는 가로 공간을 전부 차지하도록 강제 (중요!) */
.mes_text {
    flex: 1 1 auto !important;
    width: 100% !important;
    max-width: 100% !important;
    margin: 0 !important;
    padding: 0 !important;
    box-sizing: border-box !important;
    overflow-x: hidden !important; /* 가로 여백 삐져나옴 방지 */
}

/* 3. 본문 텍스트 여백 및 줄바꿈 */
.mes_text p {
    margin: 0 0 1em 0 !important;
    padding: 0 !important;
    text-align: left !important;
    word-break: break-word !important;
    overflow-wrap: anywhere !important;
}

/* 확정 */


/* 0. 메시지 상단 윗여백 확보 */
.mes, .mes_block {
    padding-top: 10px !important;
    position: relative !important;
}

/* 1. 프로필 사진 이미지만 숨기기 */
.mesAvatarWrapper .avatar {
    display: none !important;
}

/* 2. 정보 래퍼: 상단 밀착 */
.mesAvatarWrapper {
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    gap: 8px !important;
    position: absolute !important;
    top: 2px !important;
    left: auto !important;
    right: 12px !important;
    width: auto !important;
    height: auto !important;
    background: transparent !important;
    z-index: 10 !important;
}

/* 3. 번호, 시간, 토큰 폰트 정돈 */
.mesAvatarWrapper .mesIDDisplay,
.mesAvatarWrapper .mes_timer,
.mesAvatarWrapper .tokenCounterDisplay {
    display: inline-flex !important;
    align-items: center !important;
    font-size: 0.75rem !important;
    opacity: 0.75 !important;
    line-height: 1 !important;
    margin: 0 !important;
    padding: 0 !important;
}

/* 4. 번역 버튼 */
.mesAvatarWrapper .pd-message-translate-btn {
    display: inline-flex !important;
    margin-left: 4px !important;
    cursor: pointer !important;
}

/* 5. 본문 확장 */
.mes_text {
    margin-left: 0 !important;
    padding-left: 0 !important;
    width: 100% !important;
}

/* 🔥 [핵심 추가] 최신 메시지에서 편집/확장 버튼이 무조건 클릭되도록 레이어 최상단화 */
.cat-btn-group,
.cat-mes-edit-btn,
.cat-mes-trans-btn,
.cat-mes-revert-btn,
.mes_buttons {
    position: relative !important;
    z-index: 50 !important;            /* 스왑 오버레이보다 높은 계층으로 강제 승격 */
    pointer-events: auto !important;    /* 터치/클릭 강제 활성화 */
}

/* 전송 버튼(#send_but) 및 생성 중단 버튼(#stop_generating) 위치 완벽 동기화 */
#send_but,
#stop_generating,
#send_form .fa-circle-stop {
    position: relative !important;
    right: 7px !important;    /* 전송 버튼과 동일하게 왼쪽으로 9px */
    bottom: 4px !important;   /* 전송 버튼과 동일하게 위쪽으로 6px */
    cursor: pointer !important;
}



/* 1. 웹킷 기반(크롬/엣지/사파리/웹뷰) 초슬림 얄쌍한 스크롤바 */
::-webkit-scrollbar {
  width: 4px !important;               /* 가로 두께를 4px로 극도로 얄쌍하게 축소 */
  height: 4px !important;              /* 가로 스크롤도 동일하게 4px 슬림화 */
}

/* 스크롤바 트랙(뒷배경): 본문 배경과 완전히 일치시켜 투명하게 숨김 */
::-webkit-scrollbar-track {
  background: transparent !important;
}

/* 스크롤바 손잡이(바): 은은한 연회색 미니멀 라인 */
::-webkit-scrollbar-thumb {
  background: rgba(0, 0, 0, 0.15) !important;
  border-radius: 999px !important;     /* 얄쌍한 알약 라운드 */
  transition: background 0.2s ease !important;
}

/* 마우스 호버/터치 시: 살짝 더 또렷한 먹색 잉크 톤 */
::-webkit-scrollbar-thumb:hover {
  background: rgba(0, 0, 0, 0.35) !important;
}

/* 2. 파이어폭스 및 표준 브라우저 얇은 스크롤바 지원 */
* {
  scrollbar-width: thin !important;
  scrollbar-color: rgba(0, 0, 0, 0.15) transparent !important;
}

/* 🔥 핫스왑 영역 강제 표시 및 레이아웃 복구 (기능 유지) */
#CharListButtonAndHotSwaps {
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    width: 100% !important;
    min-height: 44px !important;
    overflow: visible !important;
    gap: 8px !important;
}
#HotSwapWrapper,
#HotSwapWrapper.alignitemscenter {
    display: flex !important;
    flex: 1 1 auto !important;
    min-width: 0 !important;
    width: auto !important;
    height: auto !important;
    visibility: visible !important;
    opacity: 1 !important;
    overflow: hidden !important;
}

/* 핫스왑 가로 1줄 스크롤 박스 */
#HotSwapWrapper .hotswap,
#HotSwapWrapper .hotswap.avatars_inline {
    display: flex !important;
    flex-direction: row !important;
    flex-wrap: nowrap !important;
    align-items: center !important;
    justify-content: flex-start !important;
    width: 100% !important;
    height: auto !important;
    min-height: 36px !important;
    visibility: visible !important;
    opacity: 1 !important;
    gap: 8px !important;
    overflow-x: auto !important;
    overflow-y: hidden !important;
    padding: 4px 2px !important;
    margin: 0 !important;
    -webkit-overflow-scrolling: touch;
}

/* 아바타 - 테두리/그림자 없이 심플하게, 원형 */
#HotSwapWrapper .hotswap .avatar,
#HotSwapWrapper .hotswap .inline_avatar,
#HotSwapWrapper .hotswap .character_select {
    display: inline-flex !important;
    visibility: visible !important;
    opacity: 0.85 !important;
    flex: 0 0 32px !important;
    width: 32px !important;
    height: 32px !important;
    min-width: 32px !important;
    min-height: 32px !important;
    border-radius: 50% !important;
    border: none !important;
    background: transparent !important;
    overflow: hidden !important;
    cursor: pointer !important;
    margin: 0 !important;
    padding: 0 !important;
    box-sizing: border-box !important;
    transition: opacity 0.15s !important;
}

/* 아바타 내부 이미지 */
#HotSwapWrapper .hotswap .avatar img,
#HotSwapWrapper .hotswap .inline_avatar img,
#HotSwapWrapper .hotswap .character_select img {
    display: block !important;
    visibility: visible !important;
    opacity: 1 !important;
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    border-radius: 50% !important;
}

/* 호버 시 살짝 진해지기만 (확대/테두리 강조 없음) */
#HotSwapWrapper .hotswap .avatar:hover,
#HotSwapWrapper .hotswap .inline_avatar:hover,
#HotSwapWrapper .hotswap .character_select:hover {
    opacity: 1 !important;
}

/* 스크롤바 초슬림 + 은은하게 */
#HotSwapWrapper .hotswap::-webkit-scrollbar {
    height: 2px !important;
}
#HotSwapWrapper .hotswap::-webkit-scrollbar-track {
