.completion_prompt_manager_prompt_name .fa-user,
.completion_prompt_manager_prompt_name .fa-asterisk,
.completion_prompt_manager_prompt_name [class*="fa-"] {
  color: rgba(119, 119, 119, 1) !important;
  opacity: 1 !important;
  text-shadow: none !important;
  filter: none !important;
}

/* 주입 깊이 표시(@ 1) 텍스트도 흐릿하면 같이 보정 */
.prompt-manager-injection-depth {
  color: rgba(119, 119, 119, 1) !important;
  opacity: 1 !important;
}

/* 프롬프트 컨트롤 버튼(제거/편집/토글) - 색상은 그대로, 번짐 효과만 제거 */
.prompt_manager_prompt_controls span {
  filter: none !important;
  -webkit-filter: none !important;
  backdrop-filter: none !important;
  text-shadow: none !important;
}

/* BooksOriginal-Portrait-v1 — PC book cover / mobile wide portrait. */
:root {
    --bop-enabled: 1;
    --mainFontFamily: var(--bop-chat-font, 'Noto Serif KR', Georgia, serif);
}
/* Visible portraits remain available even before the companion is installed. */
#chat .mes .mesAvatarWrapper {
    display: flex !important;
    position: static !important;
    flex: 0 0 78px !important;
    flex-direction: column !important;
    align-items: center !important;
    width: 78px !important;
    height: auto !important;
    margin: 0 14px 0 0 !important;
    padding: 10px 0 0 !important;
    pointer-events: auto !important;
}
#chat .mes .mesAvatarWrapper .avatar {
    display: block !important;
    width: 72px !important;
    height: 100px !important;
    border: 1px solid #dededb !important;
    padding: 3px !important;
    border-radius: 0 !important;
}
#chat .mes .mesAvatarWrapper .avatar img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    object-position: 50% 30% !important;
    border-radius: 0 !important;
    filter: none !important;
}
#chat .mes .name_text { font-family: 'Cormorant Garamond', 'Noto Serif KR', Georgia, serif !important; font-size: 23px !important; font-weight: 500 !important; }
#chat .mes .mes_block { min-width: 0; flex: 1 1 0; }
#top-settings-holder {
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    gap: clamp(12px, 2.2vw, 28px) !important;
    box-sizing: border-box !important;
    margin-left: auto !important;
    margin-right: auto !important;
}
@media (max-width: 767px) {
    #top-settings-holder {
        width: 100% !important;
        max-width: 100vw !important;
        justify-content: space-evenly !important;
        gap: 0 !important;
        padding-left: max(4px, env(safe-area-inset-left)) !important;
        padding-right: max(4px, env(safe-area-inset-right)) !important;
    }
    #top-settings-holder > .drawer { flex: 0 1 auto !important; min-width: 0 !important; }
    #top-settings-holder .drawer-toggle { min-width: 28px; display: flex; justify-content: center; }
    #chat .mes .mesAvatarWrapper { flex-basis: 60px !important; width: 60px !important; margin-right: 8px !important; }
    #chat .mes .mesAvatarWrapper .avatar { width: 56px !important; height: 78px !important; }
}
